                        separated_groups.append(group)

    return separated_groups

def is_balanced(group: str) -> bool:
    stack = []
    for char in group:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0

